-- User-entered per-club reference values (roadmap §7.5 personal references,
-- docs/external-benchmark-sources.md). Owner-scoped, one row per club+metric
-- (case-insensitive club), revisioned like equipment. Kept strictly separate
-- from imported measurements; never mixed into analytics cohorts.
create table public.user_reference_values (id uuid not null, owner_id uuid not null, data jsonb not null, primary key(owner_id,id));
create unique index user_reference_values_owner_metric_club on public.user_reference_values(owner_id,(data->>'metric'),lower(data->>'club'));
do $$ begin
 execute format('alter table public.user_reference_values enable row level security');
 execute format('revoke all on public.user_reference_values from public, anon, authenticated');
 execute format('grant select on public.user_reference_values to authenticated');
 execute format('create policy owner_read on public.user_reference_values for select to authenticated using ((select auth.uid()) = owner_id)');
end $$;
create function private.valid_reference_value(v jsonb) returns boolean language plpgsql immutable set search_path='' as $$ begin
 if not coalesce(jsonb_typeof(v)='object' and jsonb_typeof(v->'id')='string' and lower(v->>'id') ~ '^([0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$' and jsonb_typeof(v->'club')='string' and length(private.js_trim(v->>'club')) between 1 and 30 and v->>'metric' in ('carry','total') and jsonb_typeof(v->'valueM')='number' and (v->>'valueM') ~ '^[0-9]+(\.[0-9]+)?$' and (v->>'valueM')::numeric>0 and (v->>'valueM')::numeric<=500 and (v->'note'='null'::jsonb or (jsonb_typeof(v->'note')='string' and length(private.js_trim(v->>'note'))<=200)) and jsonb_typeof(v->'revision')='number' and (v->>'revision') ~ '^[0-9]+$' and (v->>'revision')::integer>=0,false) then return false; end if;
 return true; exception when others then return false; end $$;
-- save_reference_value: revision null creates with revision 0; an integer revision must match the stored one and is bumped by one. One dataset bump per successful write. One reference per club+metric: creating a second row for the same club+metric is a conflict.
create function private.save_reference_value(p_value jsonb) returns jsonb language plpgsql security definer set search_path='' as $$ declare u uuid:=private.lock_owner(); existing public.user_reference_values%rowtype; saved jsonb; begin
 if not coalesce(jsonb_typeof(p_value)='object' and jsonb_typeof(p_value->'id')='string' and (p_value->>'id') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$',false) then raise exception 'Invalid reference value'; end if;
 if p_value->'revision'='null'::jsonb then
  if not private.valid_reference_value(jsonb_set(p_value,'{revision}','0'::jsonb)) then raise exception 'Invalid reference value'; end if;
  if exists(select 1 from public.user_reference_values where owner_id=u and id=(p_value->>'id')::uuid) then raise exception 'Reference value conflict'; end if;
  if exists(select 1 from public.user_reference_values where owner_id=u and (data->>'metric')=p_value->>'metric' and lower(data->>'club')=lower(p_value->>'club')) then raise exception 'Reference value conflict'; end if;
  saved:=p_value || jsonb_build_object('id',(p_value->>'id')::uuid,'revision',0);
  insert into public.user_reference_values values((p_value->>'id')::uuid,u,saved);
 elsif (p_value->>'revision') ~ '^[0-9]+$' and private.valid_reference_value(p_value) then
  select * into existing from public.user_reference_values where owner_id=u and id=(p_value->>'id')::uuid for update;
  if not found or existing.data->>'revision'<>p_value->>'revision' then raise exception 'Reference value conflict'; end if;
  if (p_value->>'revision')::integer=2147483647 then raise exception 'Reference value revision limit reached'; end if;
  saved:=p_value || jsonb_build_object('id',existing.id,'revision',(p_value->>'revision')::integer+1);
  update public.user_reference_values set data=saved where owner_id=u and id=existing.id;
 else raise exception 'Invalid reference value'; end if;
 perform private.bump(u);
 return saved;
end $$;
create function private.delete_reference_value(p_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare u uuid:=private.lock_owner(); begin
 if p_id is null then raise exception 'Invalid reference value'; end if;
 if not exists(select 1 from public.user_reference_values where owner_id=u and id=p_id) then raise exception 'Reference value conflict'; end if;
 delete from public.user_reference_values where owner_id=u and id=p_id;
 perform private.bump(u); end $$;
-- Snapshot gains the userReferenceValues table; restore accepts it optionally so existing v2 backups stay restorable.
create or replace function private.dataset_page(p_table text,p_offset integer,p_limit integer) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare u uuid:=private.owner(); result jsonb; begin if p_offset is null or p_limit is null or p_offset<0 or p_limit not between 1 and 1000 then raise exception 'Invalid page'; end if; case p_table when 'sessions' then select coalesce(jsonb_agg(x.data order by x.id),'[]') into result from (select id,data from public.sessions where owner_id=u order by id offset p_offset limit p_limit) x; when 'shots' then select coalesce(jsonb_agg(x.data order by x.id),'[]') into result from (select s.id,s.payload || jsonb_build_object('id',s.id,'sessionId',s.session_id,'review',r.state,'revision',r.revision) data from public.shots s join public.reviews r on r.shot_id=s.id and r.owner_id=s.owner_id where s.owner_id=u order by s.id offset p_offset limit p_limit) x; when 'imports' then select coalesce(jsonb_agg(x.data order by x.id),'[]') into result from (select id,jsonb_build_object('id',id,'sessionId',session_id,'originalBase64',replace(encode(original,'base64'),E'\n',''),'fileHash',file_hash,'contentHash',content_hash,'parserVersion',parser_version) data from public.imports where owner_id=u order by id offset p_offset limit p_limit) x; when 'events' then select coalesce(jsonb_agg(x.data order by x.id),'[]') into result from (select id,jsonb_build_object('id',id,'shotId',shot_id,'before',before_state,'after',after_state,'createdAt',created_at,'undone',undone) data from public.review_events where owner_id=u order by id offset p_offset limit p_limit) x; when 'equipment' then select coalesce(jsonb_agg(x.data order by x.id),'[]') into result from (select id,data from public.equipment where owner_id=u order by id offset p_offset limit p_limit) x; when 'equipmentAssignments' then select coalesce(jsonb_agg(x.data order by x.shot_id),'[]') into result from (select shot_id,jsonb_build_object('shotId',shot_id,'equipmentId',equipment_id,'clubLabel',club_label) data from public.equipment_assignments where owner_id=u order by shot_id offset p_offset limit p_limit) x; when 'userReferenceValues' then select coalesce(jsonb_agg(x.data order by x.id),'[]') into result from (select id,data from public.user_reference_values where owner_id=u order by id offset p_offset limit p_limit) x; else raise exception 'Invalid dataset table'; end case; return result; end $$;
create or replace function private.restore_backup(p_dataset jsonb) returns void language plpgsql security definer set search_path='' as $$ declare u uuid:=private.lock_owner(); x jsonb; b bytea; sid uuid; shot uuid; imp public.imports%rowtype; canonical jsonb; shot_count integer; begin
 if exists(select 1 from public.sessions where owner_id=u) or exists(select 1 from public.shots where owner_id=u) or exists(select 1 from public.equipment where owner_id=u) or exists(select 1 from public.equipment_assignments where owner_id=u) or exists(select 1 from public.user_reference_values where owner_id=u) then raise exception 'Restore requires empty dataset'; end if;
 if not coalesce(jsonb_typeof(p_dataset)='object' and (p_dataset->>'version') ~ '^[0-9]+$' and jsonb_typeof(p_dataset->'sessions')='array' and jsonb_typeof(p_dataset->'shots')='array' and jsonb_typeof(p_dataset->'imports')='array' and jsonb_typeof(p_dataset->'events')='array' and jsonb_array_length(p_dataset->'sessions')<=20000 and jsonb_array_length(p_dataset->'shots')<=100000 and jsonb_array_length(p_dataset->'imports')<=20000 and jsonb_array_length(p_dataset->'events')<=200000 and (p_dataset ? 'equipment') = (p_dataset ? 'equipmentAssignments') and (not (p_dataset ? 'equipment') or (jsonb_typeof(p_dataset->'equipment')='array' and jsonb_array_length(p_dataset->'equipment')<=10000)) and (not (p_dataset ? 'equipmentAssignments') or (jsonb_typeof(p_dataset->'equipmentAssignments')='array' and jsonb_array_length(p_dataset->'equipmentAssignments')<=200000)) and (not (p_dataset ? 'userReferenceValues') or (jsonb_typeof(p_dataset->'userReferenceValues')='array' and jsonb_array_length(p_dataset->'userReferenceValues')<=1000)),false) then raise exception 'Invalid backup'; end if;
 for x in select value from jsonb_array_elements(p_dataset->'sessions') loop if not private.valid_session(x) then raise exception 'Invalid backup session'; end if; insert into public.sessions values((x->>'id')::uuid,u,x); end loop;
 for x in select value from jsonb_array_elements(p_dataset->'imports') loop sid:=(x->>'sessionId')::uuid; if not exists(select 1 from public.sessions where id=sid and owner_id=u) or not coalesce(jsonb_typeof(x->'originalBase64')='string' and jsonb_typeof(x->'fileHash')='string' and (x->>'fileHash') ~ '^[0-9a-f]{64}$' and jsonb_typeof(x->'contentHash')='string' and (x->>'contentHash') ~ '^[0-9a-f]{64}$' and jsonb_typeof(x->'parserVersion')='string',false) then raise exception 'Invalid backup import'; end if; b:=decode(x->>'originalBase64','base64'); if octet_length(b)>5242880 or encode(extensions.digest(b,'sha256'),'hex')<>x->>'fileHash' then raise exception 'Invalid backup bytes'; end if; insert into public.imports values((x->>'id')::uuid,u,sid,b,x->>'fileHash',x->>'contentHash',x->>'parserVersion'); end loop;
 for x in select value from jsonb_array_elements(p_dataset->'shots') loop sid:=(x->>'sessionId')::uuid; shot:=(x->>'id')::uuid; if not exists(select 1 from public.sessions where id=sid and owner_id=u) or not private.valid_shot(x) or not private.valid_review(x->'review') or (x->>'revision') !~ '^[0-9]+$' then raise exception 'Invalid backup shot'; end if; insert into public.shots values(shot,u,sid,x-'id'-'sessionId'-'review'-'revision'); insert into public.reviews values(shot,u,x->'review',(x->>'revision')::integer); end loop;
 if p_dataset ? 'equipment' then
  if (select count(*) from jsonb_array_elements(p_dataset->'equipment'))<>(select count(distinct value->>'id') from jsonb_array_elements(p_dataset->'equipment')) then raise exception 'Invalid backup equipment'; end if;
  for x in select value from jsonb_array_elements(p_dataset->'equipment') loop if not private.valid_equipment(x) then raise exception 'Invalid backup equipment'; end if; insert into public.equipment values((x->>'id')::uuid,u,jsonb_set(x,'{id}',to_jsonb((x->>'id')::uuid))); end loop;
 end if;
 if p_dataset ? 'equipmentAssignments' then
  if (select count(*) from jsonb_array_elements(p_dataset->'equipmentAssignments'))<>(select count(distinct value->>'shotId') from jsonb_array_elements(p_dataset->'equipmentAssignments')) then raise exception 'Invalid backup assignment'; end if;
  for x in select value from jsonb_array_elements(p_dataset->'equipmentAssignments') loop
   if not coalesce(jsonb_typeof(x)='object' and jsonb_typeof(x->'shotId')='string' and (x->>'shotId') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' and jsonb_typeof(x->'equipmentId')='string' and (x->>'equipmentId') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' and jsonb_typeof(x->'clubLabel')='string' and length(private.js_trim(x->>'clubLabel')) between 1 and 30,false) then raise exception 'Invalid backup assignment'; end if;
   shot:=(x->>'shotId')::uuid;
   if not exists(select 1 from public.shots where owner_id=u and id=shot) or not exists(select 1 from public.equipment where owner_id=u and id=(x->>'equipmentId')::uuid) then raise exception 'Invalid backup assignment'; end if;
   insert into public.equipment_assignments values(shot,u,(x->>'equipmentId')::uuid,x->>'clubLabel');
  end loop;
 end if;
 if p_dataset ? 'userReferenceValues' then
  if (select count(*) from jsonb_array_elements(p_dataset->'userReferenceValues'))<>(select count(distinct value->>'id') from jsonb_array_elements(p_dataset->'userReferenceValues')) then raise exception 'Invalid backup reference value'; end if;
  if (select count(*) from jsonb_array_elements(p_dataset->'userReferenceValues'))<>(select count(distinct (lower(value->>'club'),value->>'metric')) from jsonb_array_elements(p_dataset->'userReferenceValues')) then raise exception 'Invalid backup reference value'; end if;
  for x in select value from jsonb_array_elements(p_dataset->'userReferenceValues') loop if not private.valid_reference_value(x) then raise exception 'Invalid backup reference value'; end if; insert into public.user_reference_values values((x->>'id')::uuid,u,jsonb_set(x,'{id}',to_jsonb((x->>'id')::uuid))); end loop;
 end if;
 for imp in select * from public.imports where owner_id=u loop
 select count(*),jsonb_build_object('headers',(select jsonb_agg(k) from jsonb_object_keys((select payload->'raw' from public.shots where owner_id=u and session_id=imp.session_id order by (payload->>'rowIndex')::integer limit 1)) k),'shots',jsonb_agg(payload order by (payload->>'rowIndex')::integer)) into shot_count,canonical from public.shots where owner_id=u and session_id=imp.session_id;
 if shot_count=0 or shot_count>20000 or exists(select 1 from (select (payload->>'rowIndex')::integer as n,row_number() over(order by (payload->>'rowIndex')::integer) as expected from public.shots where owner_id=u and session_id=imp.session_id) rows where n<>expected) or private.canonical_hash(canonical)<>imp.content_hash then raise exception 'Invalid backup content'; end if; perform private.validate_source(imp.original,canonical,imp.parser_version);
 end loop;
 for x in select value from jsonb_array_elements(p_dataset->'events') loop shot:=(x->>'shotId')::uuid; if not exists(select 1 from public.shots where id=shot and owner_id=u) or not private.valid_review(x->'before') or not private.valid_review(x->'after') then raise exception 'Invalid backup event'; end if; insert into public.review_events(id,owner_id,shot_id,before_state,after_state,created_at,undone) values((x->>'id')::uuid,u,shot,x->'before',x->'after',(x->>'createdAt')::timestamptz,coalesce((x->>'undone')::boolean,false)); end loop;
 if exists(select 1 from public.sessions s where owner_id=u and not exists(select 1 from public.imports i where i.session_id=s.id and i.owner_id=u)) then raise exception 'Session missing import'; end if; perform private.bump(u); end $$;
revoke all on function private.valid_reference_value(jsonb),private.save_reference_value(jsonb),private.delete_reference_value(uuid) from public, anon, authenticated;
grant execute on function private.save_reference_value(jsonb),private.delete_reference_value(uuid) to authenticated;
create function public.save_reference_value(p_value jsonb) returns jsonb language sql security invoker set search_path='' as $$ select private.save_reference_value(p_value) $$;
create function public.delete_reference_value(p_id uuid) returns void language sql security invoker set search_path='' as $$ select private.delete_reference_value(p_id) $$;
revoke all on function public.save_reference_value(jsonb),public.delete_reference_value(uuid) from public, anon;
grant execute on function public.save_reference_value(jsonb),public.delete_reference_value(uuid) to authenticated;
